.hns1-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.hns1-root,.hns1-root *,.hns1-root *::before,.hns1-root *::after{box-sizing:border-box}
.hns1-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.hns1-root img{display:block;border:0;max-width:none}
.hns1-root [hidden]{display:none!important}
.hns1-root .n1_24464bbbbb{align-content:stretch;display:flex;flex:1 0 0;height:18px;align-items:center;justify-content:space-between;min-width:1px;padding-left:4px;padding-right:3px;position:relative;border-radius:4px}
.hns1-root .n1_24465bbbbb{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:color:var(--basic\/eee,var(--wa-text, #eee));white-space:nowrap}
.hns1-root .n1_24466bbbbb{background-color:color-mix(in srgb, var(--wa-bg, rgb(0 0 0)) 40%, transparent);align-content:stretch;display:flex;height:18px;align-items:center;justify-content:flex-end;padding:5px;position:relative;border-radius:4px;flex-shrink:0;width:34.5px}
.hns1-root .n1_24467bbbbb{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:12px;text-align:right;color:var(--wa-text, #fff);white-space:nowrap}
.hns1-root[data-theme="light"]{background:var(--wa-bg, #eef4f1);color:var(--wa-text, #10231d)}
